"""Independent source-based review, with printed-source key exposure explicitly disclosed."""
from pathlib import Path
import json,hashlib,datetime,sys,re
from PIL import Image
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
from validate import question_hash,schema_errors
WHO='repair_assignment_source_bindings:independent-reviewer';D='audits/assignment-coverage'
read=lambda p:json.loads((R/p).read_text());sha=lambda p:hashlib.sha256((R/p).read_bytes()).hexdigest()
def write(p,x):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);assert not p.exists(),p;p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
flags={11:{5:{'sourceSupport':'The physical-page51 citation for item5 is labeled equation, but that item region contains only the prose motor/gearbox/efficiency input prompt; the multiplication is on page52. Change page51 to statement/premise. The page52 equation citation, effective-transfer qualification and numerical solution are correct.'}},12:{6:{'distractors':'The pre-answer stem explicitly forbids an unconditional hard-deadline guarantee, while the three distractors are all unconditional guarantee or validation-bypass claims. This exposes the requested conclusion instead of neutrally testing the course statement. Use a neutral source-interpretation stem and retain the timing-guarantee qualification in the solution; preserve the source-only/no-runtime scope.'},10:{'distractors':'The pre-answer assumption says that compliance can store and return energy. Only the compliance option names that mechanism, so the assumption supplies the energy-taking property the stem asks the learner to identify. Keep the neutral mechanism question; move the compliance-specific storage/return explanation to the solution, or state a mechanism-neutral convention about taking up versus dissipating energy.'}}}
sourceobs=read(f'{D}/W11-W12-recovery-independent-source-observations.json');obs={x['physicalPage']:x for x in sourceobs['pages']};now=datetime.datetime.now(datetime.timezone.utc).isoformat();dims=['sourceSupport','assumptions','answerSet','distractors','calculations','figureFidelity','explanation','difficulty','duplication']
for week in [11,12]:
 B=f'ASSIGN-W{week}';sp=f'{D}/W{week}-recovery-independent-prekey-seal.json';seal=read(sp);assert not seal['generatedKeyOpened'];assert sha(seal['packetPath'])==seal['packetSha256'];assert sha(seal['checksPath'])==seal['checksSha256'];assert sha(seal['sourceObservationsPath'])==seal['sourceObservationsSha256'];binding=read(f'audits/blind-binding-{B}.json');bindings={x['id']:x for x in binding['questions']};b=read(f'data/question-batches/{B}.json');responses={x['questionId']:x for x in seal['answers']};reveal=read(f'{D}/W{week}-recovery-independent-reveal.json');reviews=[];accepted={};findings=[];coverage=[]
 normalized=lambda s:re.sub(r'\s+',' ',s.strip()).casefold();mine={normalized(q['stem']):q['id']for q in b['questions']};collisions=[]
 for p in (R/'data/question-batches').glob('*.json'):
  other=json.loads(p.read_text());other=other if isinstance(other,list)else other.get('questions',[])
  for q in other:
   if q['id']not in bindings and normalized(q['stem'])in mine:collisions.append([mine[normalized(q['stem'])],q['id']])
 assert not collisions,collisions
 for q in b['questions']:
  qid=q['id'];n=int(qid[-3:]);a=responses[qid];assert q['version']==bindings[qid]['version']and question_hash(q)==bindings[qid]['sha256'];assert set(a['selectedOptionIds'])==set(q['correctOptionIds']);assert WHO not in [q['authorId']]+q.get('revisionAuthors',[]);assert sha(q['originalRecordPath'])==q['originalRecordSha256'];original=read(q['originalRecordPath']);assert original['id']==q['assignmentSourceItemId'];slides=list(dict.fromkeys(c['slideId']for c in q['citations']));evidence=[]
  for c in q['citations']:
   p=c['physicalPage'];assert c['sourceId']=='assignments'and p in obs;assert c['sourceSha256']==sourceobs['sourceSha256']
   if any(x['physicalPage']==p for x in evidence):continue
   o=obs[p];assert sha(o['imagePath'])==o['imageSha256'];evidence.append({'sourceId':'assignments','physicalPage':p,'imagePath':o['imagePath'],'imageSha256':o['imageSha256'],'dimensions':list(Image.open(R/o['imagePath']).size),'visualInspection':'complete','viewedAt':sourceobs['inspectedAt'],'sourceAnswerExposure':True,'observation':o['observation']})
  issues=flags[week].get(n,{})
  rec={'id':f'REV-{qid}-v{q["version"]}-recovery-independent','questionId':qid,'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':WHO,'decision':'flagged'if issues else'verified','reviewedAt':now,'sourceVersions':{'assignments':sourceobs['sourceSha256']},'reviewedSlideIds':slides,'independentAnswerOptionIds':a['selectedOptionIds'],'solvedBeforeAnswerSeen':False,'checks':{d:d not in issues for d in dims},'reasoning':a['reasoning']+' Current generated-key-hidden answers were sealed before opening the keyed batch. Printed original answers were visible during independent actual-pixel inspection, so this is independent re-derivation, not fully blind review. Current complete options, explanations, formulas, units, assumptions, exact citation kinds/regions and immutable-original bindings were checked.','findings':list(issues.values()),'reviewType':'assignment_independent_rederivation_with_source_key_exposure','priorExposure':'Original assignment printed answers visible; current generated keys hidden until the persisted response seal.','blindAnswerRecord':sp,'blindAnswerRecordSha256':sha(sp),'firstCurrentKeyOpenedAt':reveal['firstCurrentKeyOpenedAt'],'sourceInspectionEvidence':evidence,'independentCheckEvidence':{'path':seal['checksPath'],'sha256':seal['checksSha256']},'originalSourceRecordChecked':{'path':q['originalRecordPath'],'sha256':q['originalRecordSha256'],'printedItemNumber':original['printedItemNumber'],'sourcePages':original['physicalPages']}}
  assert not schema_errors(rec,read('data/schema.review.json')),schema_errors(rec,read('data/schema.review.json'));reviews.append(rec);coverage.append({'originalItemId':q['assignmentSourceItemId'],'questionId':qid,'physicalPages':original['physicalPages'],'decision':rec['decision'],'sourceOriginalPreserved':True,'conceptCovered':True})
  if issues:findings.append({'questionId':qid,'questionSha256':question_hash(q),'failedChecks':list(issues),'findings':list(issues.values())})
  else:accepted[qid]=question_hash(q)
 rp=f'data/reviews/{B}-v1-independent-recovery.json';write(rp,reviews);cp=read(seal['checksPath']);summary={'batchId':B,'frozenAt':now,'reviewedCount':10,'keysMatching':10,'verifiedCount':len(accepted),'flaggedCount':len(findings),'acceptedQuestionHashes':accepted,'flaggedQuestions':findings,'reviewPath':rp,'reviewSha256':sha(rp),'actualAssignmentPages':list(range(50,56))if week==11 else list(range(56,60)),'sourceKeyExposure':True,'generatedKeysHiddenUntilSeal':True,'fullyBlind':False,'independentChecks':{'namedCount':cp['namedCount'],'variedAssertions':cp['variedAssertions'],'path':seal['checksPath']},'itemCoverage':coverage,'boundedAdditionalContentGaps':[],'coverageConclusion':'All ten immutable original items are explicitly represented with their source-specific qualifications. No additional original concept omission found. The flagged narrow metadata/answer-cue items remain outside the accepted pool.','exactNormalizedStemCollisions':collisions,'executionBoundary':'Installed standard-library arithmetic only. No author script, training, model/download/install, ROS, hardware, network or browser runtime; product browser verification is separate.'};write(f'{D}/{B}-recovery-independent-review-summary.json',summary);print(json.dumps({k:summary[k]for k in ['batchId','verifiedCount','flaggedCount','keysMatching','reviewPath','reviewSha256']}))
